assignments.referenceSolution:
The solution keeps each layer to one job. The controller adapts DTOs, the service owns the rules and ordering (validate, then mutate), and the repositories hide storage behind Protocols, so swapping in a database changes no rule. Tests inject the in-memory repositories directly and assert on observable state.

**`library/models.py`**

```python
from dataclasses import dataclass


@dataclass
class Book:
    isbn: str
    title: str
    copies_available: int


@dataclass
class Member:
    id: int
    name: str
    max_loans: int = 3


@dataclass(frozen=True)
class Loan:
    member_id: int
    isbn: str
```

**`library/exceptions.py`**

```python
class LibraryError(Exception):
    """Base class so the controller can catch every domain failure in one clause."""


class MemberNotFoundError(LibraryError):
    pass


class BookNotFoundError(LibraryError):
    pass


class NoCopiesAvailableError(LibraryError):
    pass


class LoanLimitExceededError(LibraryError):
    pass
```

**`library/repositories.py`**

```python
from typing import Protocol

from library.models import Book, Loan, Member


class BookRepository(Protocol):
    def find_by_isbn(self, isbn: str) -> Book | None: ...
    def save(self, book: Book) -> Book: ...


class MemberRepository(Protocol):
    def find_by_id(self, member_id: int) -> Member | None: ...


class LoanRepository(Protocol):
    def add(self, loan: Loan) -> Loan: ...
    def count_for_member(self, member_id: int) -> int: ...


class InMemoryBookRepository:
    def __init__(self, books: list[Book] | None = None) -> None:
        self._books = {b.isbn: b for b in books or []}

    def find_by_isbn(self, isbn: str) -> Book | None:
        return self._books.get(isbn)

    def save(self, book: Book) -> Book:
        self._books[book.isbn] = book
        return book


class InMemoryMemberRepository:
    def __init__(self, members: list[Member] | None = None) -> None:
        self._members = {m.id: m for m in members or []}

    def find_by_id(self, member_id: int) -> Member | None:
        return self._members.get(member_id)


class InMemoryLoanRepository:
    def __init__(self) -> None:
        self._loans: list[Loan] = []

    def add(self, loan: Loan) -> Loan:
        self._loans.append(loan)
        return loan

    def count_for_member(self, member_id: int) -> int:
        return sum(1 for loan in self._loans if loan.member_id == member_id)
```

**`library/service.py`**

```python
from library.exceptions import (
    BookNotFoundError,
    LoanLimitExceededError,
    MemberNotFoundError,
    NoCopiesAvailableError,
)
from library.models import Loan
from library.repositories import BookRepository, LoanRepository, MemberRepository


class LibraryService:
    """Business rules only: plain values in, domain objects out, no DTOs."""

    def __init__(self, books: BookRepository, members: MemberRepository, loans: LoanRepository) -> None:
        self._books = books
        self._members = members
        self._loans = loans

    def lend_book(self, member_id: int, isbn: str) -> Loan:
        member = self._members.find_by_id(member_id)
        if member is None:
            raise MemberNotFoundError(f"member {member_id} not found")
        book = self._books.find_by_isbn(isbn)
        if book is None:
            raise BookNotFoundError(f"book {isbn} not found")
        if book.copies_available <= 0:
            raise NoCopiesAvailableError(f"no copies of {isbn} left")
        if self._loans.count_for_member(member_id) >= member.max_loans:
            raise LoanLimitExceededError(f"member {member_id} is at the loan limit")
        # every check passed: only now do we mutate state
        book.copies_available -= 1
        self._books.save(book)
        return self._loans.add(Loan(member_id, isbn))
```

**`library/controller.py`**

```python
from dataclasses import dataclass
from enum import Enum

from library.exceptions import LibraryError
from library.service import LibraryService


class ResponseStatus(Enum):
    SUCCESS = "SUCCESS"
    FAILURE = "FAILURE"


@dataclass(frozen=True)
class LendBookRequest:
    member_id: int
    isbn: str


@dataclass(frozen=True)
class LendBookResponse:
    status: ResponseStatus
    message: str = ""


class LibraryController:
    """Unwrap the request DTO, call the service, wrap the response DTO."""

    def __init__(self, service: LibraryService) -> None:
        self._service = service

    def lend_book(self, request: LendBookRequest) -> LendBookResponse:
        try:
            self._service.lend_book(request.member_id, request.isbn)
        except LibraryError as exc:
            return LendBookResponse(ResponseStatus.FAILURE, str(exc))
        return LendBookResponse(ResponseStatus.SUCCESS)
```

**`tests/test_lend_book.py`**

```python
import pytest

from library.controller import LendBookRequest, LibraryController, ResponseStatus
from library.exceptions import LoanLimitExceededError, NoCopiesAvailableError
from library.models import Book, Member
from library.repositories import (
    InMemoryBookRepository,
    InMemoryLoanRepository,
    InMemoryMemberRepository,
)
from library.service import LibraryService


def make(books, members):
    book_repo = InMemoryBookRepository(books)
    loan_repo = InMemoryLoanRepository()
    service = LibraryService(book_repo, InMemoryMemberRepository(members), loan_repo)
    return service, LibraryController(service), book_repo, loan_repo


def test_successful_loan_decrements_copies_and_records_loan() -> None:
    service, controller, books, loans = make([Book("111", "SICP", 2)], [Member(1, "Asha")])
    response = controller.lend_book(LendBookRequest(1, "111"))
    assert response.status is ResponseStatus.SUCCESS
    assert books.find_by_isbn("111").copies_available == 1
    assert loans.count_for_member(1) == 1


def test_unknown_member_and_unknown_book_fail_cleanly() -> None:
    _, controller, books, _ = make([Book("111", "SICP", 1)], [Member(1, "Asha")])
    assert controller.lend_book(LendBookRequest(9, "111")).status is ResponseStatus.FAILURE
    assert controller.lend_book(LendBookRequest(1, "nope")).status is ResponseStatus.FAILURE
    assert books.find_by_isbn("111").copies_available == 1


def test_no_copies_left_raises_in_service() -> None:
    service, _, _, _ = make([Book("111", "SICP", 0)], [Member(1, "Asha")])
    with pytest.raises(NoCopiesAvailableError):
        service.lend_book(1, "111")


def test_loan_limit_is_enforced_and_failed_call_does_not_change_stock() -> None:
    books = [Book(str(i), f"B{i}", 5) for i in range(4)]
    service, controller, repo, loans = make(books, [Member(1, "Asha", max_loans=3)])
    for i in range(3):
        service.lend_book(1, str(i))
    with pytest.raises(LoanLimitExceededError):
        service.lend_book(1, "3")
    assert repo.find_by_isbn("3").copies_available == 5
    assert loans.count_for_member(1) == 3
    response = controller.lend_book(LendBookRequest(1, "3"))
    assert response.status is ResponseStatus.FAILURE
    assert "loan limit" in response.message
```

Run the tests from the project root with `pytest -q`.
